	'messages:sitecssprotected' => 'hi:आपको यह CSS पृष्ठ सम्पादित करने की अनुमति नहीं है क्योंकि यह सभी पाठकों को प्रभावित कर सकती है।',
	'messages:sitejsonprotected' => 'hi:आपको यह JSON पृष्ठ सम्पादित करने की अनुमति नहीं है क्योंकि यह सभी पाठकों को प्रभावित कर सकती है।',
	'messages:sitejsprotected' => 'hi:आपको यह जावास्क्रिप्ट पृष्ठ सम्पादित करने की अनुमति नहीं है क्योंकि यह सभी पाठकों को प्रभावित कर सकती है।',
	'messages:siterawhtmlprotected' => 'hi:आपको इस पृष्ठ को संपादित करने की अनुमति नहीं है क्योंकि इसमें सीधा HTML शामिल है जिसे सभी आगंतुकों को प्रभावित करने के लिए संशोधित किया जा सकता है।',
	'messages:mycustomjsonprotected' => 'hi:आपको यह JSON पृष्ठ सम्पादित करने की अनुमति नहीं है।',
