	'messages:botpasswords-insert-failed' => 'hi:बॉट नाम "$1" को जोड़ने में विफल हुआ। क्या यह पहले से है?',
	'messages:botpasswords-update-failed' => 'hi:बॉट नाम "$1" को अद्यतन करने में विफल हुआ। क्या ये हट गया?',
	'messages:botpasswords-created-body' => 'hi:सदस्य "$2" के बॉट नाम "$1" के लिए पासवर्ड निर्मित हुआ।',
	'messages:botpasswords-updated-title' => 'hi:बॉट पासवर्ड अद्यतन हुआ',
	'messages:botpasswords-updated-body' => 'hi:सदस्य "$2" के बॉट नाम "$1" का पासवर्ड सफलतापूर्वक अद्यतन हुआ।',
	'messages:botpasswords-deleted-title' => 'hi:बॉट पासवर्ड हट गया',
	'messages:botpasswords-deleted-body' => 'hi:सदस्य "$2" के बॉट नाम "$1" का पासवर्ड हट गया।',
	'messages:botpasswords-newpassword' => 'hi:<strong>$1</strong> के साथ लॉगिन करने के लिए आपका नया पासवर्ड <strong>$2</strong> है। <em>भविष्य के लिए इसे याद रखें</em> <br> (पुराने बॉट के लिए लॉगिन नाम और बॉट का सदस्य नाम समान चाहिए होता है, तो आप <strong>$3</strong> का उपयोग अपने सदस्य नाम के रूप में और <strong>$4</strong> का उपयोग अपने पासवर्ड के रूप में कर सकते हैं।)',
	'messages:botpasswords-no-provider' => 'hi:BotPasswordsSessionProvider उपलब्ध नहीं है।',
