	'messages:uploaded-hostile-svg' => 'hi:अपलोड की गयी एसवीजी फाइल के शैली अवयव में असुरक्षित सीएसएस पायी गयी।',
	'messages:uploaded-event-handler-on-svg' => 'hi:सेटिंग ईवेंट हैंडलर (आयोजन प्रबन्धनकर्ता वरियता) <code>$1="$2"</code> एसवीजी फ़ाइल में अनुमत नहीं है।',
	'messages:uploaded-href-attribute-svg' => 'hi:&lt;a&gt; तत्व केवल डेटा से लिंक किया जा सकता है: (अंतःस्थापित दस्तावेज), http:// or https://, या टुकड़ा (#, समरूप दस्तावेज) लक्ष्य| अन्य तत्वों के लिए, जैसे &lt;image&gt;, केवल डेटा: और टुकड़ों की अनुमति है| अपने एसवीजी को निर्यात करते समय छवियों को अंतःस्थापित करने का प्रयास करें| मिला <code> &lt;$1 $2="$3"&gt;</code>।',
	'messages:uploaded-href-unsafe-target-svg' => 'hi:अपलोड की गयी फ़ाइल में असुरक्षित लक्ष्य <code>&lt;$1 $2="$3"&gt;</code> पाये गए।',
	'messages:uploaded-animate-svg' => 'hi:चिप्पि "animate" पायी गई जिससे href परिवर्तित हो सकता है, अपलोड की गयी फ़ाइल में "from" विशेषता <code>&lt;$1 $2="$3"&gt;</code> काम में ली जा रही है।',
	'messages:uploaded-setting-event-handler-svg' => 'hi:विकल्प आयोजन-संभालने वाला अवरोधित है, एसवीजी फ़ाइल में मिला <code>&lt;$1 $2="$3"&gt;</code> है।',
	'messages:uploaded-setting-href-svg' => 'hi:"set" का उपयोग कर "href" जोड़ना अवरोधित है।',
	'messages:uploaded-wrong-setting-svg' => 'hi:"set" का उपयोग कर किसी अन्य डाटा, लिपि से कार्य अवरोधित है। एसवीजी फ़ाइल में मिला <code>&lt;set to="$1"&gt;</code> है।',
	'messages:uploaded-setting-handler-svg' => 'hi:एसवीजी जो "handler" जोड़ता है, अवरोधित है। उससे मिला <code>$1="$2"</code> है।',
	'messages:uploaded-remote-url-svg' => 'hi:एसवीजी जो रिमोट पते द्वारा शैली तय करता है, अवरोधित है। उससे <code>$1="$2"</code> मिला है।',
	'messages:uploaded-image-filter-svg' => 'hi:पते के साथ छवि छन्नी मिला: <code>&lt;$1 $2="$3"&gt;</code> एसवीजी फ़ाइल में।',
	'messages:filename-thumb-name' => 'hi:यह एक थंबनेल शीर्षक की तरह लग रहा है। कृपया थंबनेल  वापस विकि पर अपलोड न करें। अन्यथा, कृपया फ़ाइल नाम ठीक करें।',
	'messages:filename-prefix-blacklist' => 'hi:#<!-- leave this line exactly as it is --> <pre>
